foreach (string command in commands)
    if (command == "undo")
    else if (command == "redo")
    else
        if (command.StartsWith("type ", StringComparison.Ordinal))
            buffer += command[5..];
        else
            buffer = buffer[..Math.Max(0, buffer.Length - int.Parse(command[7..], CultureInfo.InvariantCulture))];
    }
